/**
 * Smooth Shadows: a stack of soft shadow layers from two numbers. `size` sets
 * how far the shadow reaches and `intensity` how dark it gets; the layers are
 * spaced so light seems to fall from above. Use the string as `box-shadow`,
 * or write it into a theme as a token.
 */

export interface SmoothShadowOptions {
  /** How far the shadow reaches, in pixels. */
  size?: number;
  /** Peak opacity of the stack, in percent. */
  intensity?: number;
  /** Space-separated RGB, or a CSS variable holding one. */
  color?: string;
  /** Add a faint outline that keeps the edge crisp on light backgrounds. */
  ring?: boolean;
  /** Draw that outline at half a pixel, which reads as a hairline on dense screens. */
  hairline?: boolean;
}

const round = (n: number, step = 10) => Math.round(n * step) / step;

/** The shadow layers, nearest first. */
export function smoothShadowLayers({ size = 8, intensity = 4, color = "0 0 0" }: SmoothShadowOptions = {}) {
  const count = Math.min(8, Math.max(2, Math.round(size / 2)));
  return Array.from({ length: count }, (_, k) => {
    const f = (k + 1) / count;
    const y = round(size * 1.25 * f * f);
    const blur = round(size * 0.5 * f + y * 0.4);
    const alpha = round((intensity / 100) * (1 - k / count), 1000);
    return { y, blur, alpha, css: `0px ${y}px ${blur}px rgb(${color} / ${alpha})` };
  });
}

/** A `box-shadow` value. */
export function smoothShadow(options: SmoothShadowOptions = {}): string {
  const { intensity = 4, color = "0 0 0", ring = false, hairline = false } = options;
  const layers = smoothShadowLayers(options).map((l) => l.css);
  if (ring) layers.unshift(`0 0 0 ${hairline ? 0.5 : 1}px rgb(${color} / ${round(Math.min(1, (intensity * 1.5) / 100), 1000)})`);
  return layers.join(", ");
}

/** A theme token: `--shadow-<name>` holding the stack, tinted by `--shadow-color`. */
export function smoothShadowToken(name: string, options: Omit<SmoothShadowOptions, "color"> = {}): string {
  const value = smoothShadow({ ...options, color: "var(--shadow-color, 0 0 0)" });
  return `--shadow-${name}: ${value.split(", ").join(",\n  ")};`;
}
